'use strict';

const sharp=require('sharp');
const {readPublicSupabaseConfig}=require('../lib/happyad-server-env');
const SUPABASE=readPublicSupabaseConfig();
const LOGO=Buffer.from('','base64');

function clean(value){return String(value==null?'':value).trim();}
function originOf(event){try{const raw=clean(event&&event.rawUrl);if(raw)return new URL(raw).origin;}catch(_e){}const h=(event&&event.headers)||{};const host=clean(h['x-forwarded-host']||h['X-Forwarded-Host']||h.host||h.Host);const proto=clean(h['x-forwarded-proto']||h['X-Forwarded-Proto']||'https').split(',')[0].trim()||'https';return host?proto+'://'+host:'';}
async function fetchFast(url,options,ms){const ac=new AbortController();const t=setTimeout(()=>ac.abort(),Math.max(650,Number(ms)||2200));try{return await fetch(url,Object.assign({},options||{},{signal:ac.signal}));}finally{clearTimeout(t);}}
function firstMediaValue(value){
  if(value===null||value===undefined)return '';
  if(typeof value==='string'){const s=clean(value);if(!s)return '';if((s[0]==='['&&s[s.length-1]===']')||(s[0]==='{'&&s[s.length-1]==='}')){try{return firstMediaValue(JSON.parse(s));}catch(_e){}}return s;}
  if(Array.isArray(value)){for(const x of value){const v=firstMediaValue(x);if(v)return v;}return '';}
  if(typeof value==='object'){for(const k of ['url','publicUrl','public_url','src','path','storage_path','storagePath','file_path','filePath','media_url','mediaUrl','image_url','imageUrl','photo_url','photoUrl','video_url','videoUrl','thumbnail_url','thumbnailUrl','poster_url','posterUrl','cover_url','coverUrl','original_url','originalUrl','compressed_url','compressedUrl']){const v=firstMediaValue(value[k]);if(v)return v;}}
  return '';
}
function absoluteMedia(value){let src=clean(value);if(!src)return '';if(/^https?:\/\//i.test(src))return src;src=src.replace(/^\/+/, '').replace(/^happyad-media\//i,'');if(!SUPABASE.ready)return '';return SUPABASE.url+'/storage/v1/object/public/happyad-media/'+encodeURI(src);}
function isVideoRow(row,hint){row=row||{};const kind=clean(row.media_type||row.home_media_type||row.type||row.kind||row.mime_type||hint).toLowerCase();if(/video|reel|clip|mp4|webm|mov|m4v/.test(kind))return true;const raw=firstMediaValue(row.video_url||row.video_url_compressed||row.compressed_video_url||row.video_url_original||row.original_video_url||row.media_url||row.home_media_url||row.media_path||row.media_urls||row.files);return /\.(mp4|webm|mov|m4v)(?:$|[?#])/i.test(raw);}
function mediaCandidate(row,hint){
  row=row||{};const video=isVideoRow(row,hint);
  const poster=firstMediaValue(row.thumbnail_url||row.thumbnailUrl||row.poster_url||row.posterUrl||row.cover_url||row.coverUrl||row.home_thumbnail_url||row.homeThumbnailUrl||row.preview_url||row.previewUrl||row.marketplace_cover_url||row.marketplaceCoverUrl||row.image_url||row.imageUrl||row.photo_url||row.photoUrl);
  const media=firstMediaValue(row.marketplace_cover_url||row.marketplaceCoverUrl||row.home_media_url||row.homeMediaUrl||row.media_url||row.mediaUrl||row.media_path||row.mediaPath||row.image_url||row.imageUrl||row.photo_url||row.photoUrl||row.video_url_compressed||row.videoUrlCompressed||row.compressed_video_url||row.compressedVideoUrl||row.video_url_original||row.videoUrlOriginal||row.original_video_url||row.originalVideoUrl||row.video_url||row.videoUrl||row.media_urls||row.mediaUrls||row.images||row.photos||row.files||row.gallery||row.medias||row.media||row.marketplace_media||row.marketplaceMedia);
  let value=video?(poster||media):(media||poster);if(video&&!poster&&/\.(mp4|webm|mov|m4v)(?:$|[?#])/i.test(media))value='';return absoluteMedia(value);
}
function allowedRemote(url){try{const u=new URL(url);return u.protocol==='https:';}catch(_e){return false;}}
async function loadPost(postId){if(!postId||!SUPABASE.ready)return null;try{const url=SUPABASE.url+'/rest/v1/happyad_posts?id=eq.'+encodeURIComponent(postId)+'&select=*&limit=1';const r=await fetchFast(url,{headers:{apikey:SUPABASE.publishableKey,Authorization:'Bearer '+SUPABASE.publishableKey,Accept:'application/json'}},1700);if(!r.ok)return null;const a=await r.json();return Array.isArray(a)&&a[0]?a[0]:null;}catch(_e){return null;}}
async function logoBadge(size){
  size=size||88;
  /* V886: logo Fyblic bien visible sur le media, dans un disque noir propre, sans contour blanc. */
  const S=Math.max(56,Math.round(size));
  const inner=Math.round(S*0.72);
  const base=Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${S}" height="${S}"><circle cx="${S/2}" cy="${S/2}" r="${(S/2)-2}" fill="rgba(0,0,0,0.88)"/></svg>`);
  const logo=await sharp(LOGO).resize(inner,inner,{fit:'contain'}).png().toBuffer();
  return sharp(base).composite([{input:logo,gravity:'centre'}]).png().toBuffer();
}
async function fallbackCard(video){
  const W=1200,H=900;
  const bg=Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#05080d"/><stop offset="1" stop-color="#111820"/></linearGradient></defs><rect width="${W}" height="${H}" fill="url(#g)"/></svg>`);
  const logo=await sharp(LOGO).resize(210,210,{fit:'contain'}).png().toBuffer();
  const brand=Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="560" height="120"><text x="0" y="82" font-family="Arial,Helvetica,sans-serif" font-size="76" font-weight="700" fill="white">Fyblic</text></svg>');
  const layers=[{input:logo,top:250,left:495},{input:brand,top:500,left:335}];
  if(video){const play=Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="180" height="180"><circle cx="90" cy="90" r="68" fill="rgba(0,0,0,.62)" stroke="white" stroke-width="5"/><path d="M76 56v68l55-34z" fill="white"/></svg>');layers.push({input:play,gravity:'centre'});}
  return sharp(bg).composite(layers).jpeg({quality:86,mozjpeg:true}).toBuffer();
}
async function adaptiveCard(input,video){
  const W=1200,H=900;
  const normalized=await sharp(input,{failOn:'none'}).rotate().toBuffer();
  const background=await sharp(normalized).resize(W,H,{fit:'cover',position:'centre'}).blur(30).modulate({brightness:.54,saturation:.82}).jpeg({quality:80}).toBuffer();
  /* V882: la vraie publication reste entiere. Aucun crop du media principal. */
  const foreground=await sharp(normalized).resize(W-34,H-34,{fit:'contain',position:'centre',background:{r:0,g:0,b:0,alpha:0}}).png().toBuffer();
  /* V894: on conserve le petit logo de la zone basse WhatsApp et on ajoute un second logo dans le media, en bas a droite. */
  const mediaBadge=await logoBadge(118);
  /* V896: position absolue, calculee depuis le canevas 1200x900. Pas de gravity :
     le badge ne peut plus revenir en haut a gauche. */
  const badgeSize=118, badgeMargin=28;
  const badgeLeft=W-badgeSize-badgeMargin;
  const badgeTop=H-badgeSize-badgeMargin;
  const layers=[{input:foreground,gravity:'centre'},{input:mediaBadge,top:badgeTop,left:badgeLeft}];
  if(video){const play=Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="190" height="190"><circle cx="95" cy="95" r="72" fill="rgba(0,0,0,.64)" stroke="white" stroke-width="6"/><path d="M80 58v74l60-37z" fill="white"/></svg>');layers.push({input:play,gravity:'centre'});}
  return sharp(background).composite(layers).jpeg({quality:87,mozjpeg:true}).toBuffer();
}
function decodePart(value){try{return decodeURIComponent(clean(value));}catch(_e){return clean(value);}}
function imagePostId(event){
  const q=(event&&event.queryStringParameters)||{};
  if(clean(q.post))return decodePart(q.post);
  const routed=clean(q.path).replace(/^\/+|\/+$/g,'');
  if(routed){const parts=routed.split('/').filter(Boolean).map(decodePart);return clean(parts[0]);}
  try{const raw=clean(event&&event.rawUrl);if(raw){const u=new URL(raw),parts=u.pathname.split('/').filter(Boolean).map(decodePart),i=parts.indexOf('share-image');if(i>=0&&parts[i+1])return clean(parts[i+1]);}}catch(_e){}
  const parts=clean(event&&event.path).split('/').filter(Boolean).map(decodePart),i=parts.indexOf('share-image');return i>=0&&parts[i+1]?clean(parts[i+1]):'';
}
exports.handler=async function(event){
  const q=event.queryStringParameters||{},postId=imagePostId(event),hint=clean(q.type);let row=null,source=clean(q.image),video=/video|reel|clip|^v$/i.test(hint);
  try{
    if(!source||!allowedRemote(source)){row=await loadPost(postId);if(row)video=isVideoRow(row,hint);source=mediaCandidate(row||{},video?'video':'photo');}
    if(source&&allowedRemote(source)){const r=await fetchFast(source,{headers:{Accept:'image/avif,image/webp,image/*,*/*;q=0.8'}},2800);if(r.ok){const input=Buffer.from(await r.arrayBuffer());const out=await adaptiveCard(input,video);return {statusCode:200,isBase64Encoded:true,headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=86400, s-maxage=31536000, immutable','Access-Control-Allow-Origin':'*'},body:out.toString('base64')};}}
  }catch(_e){}
  const out=await fallbackCard(video);return {statusCode:200,isBase64Encoded:true,headers:{'Content-Type':'image/jpeg','Cache-Control':'public, max-age=20, s-maxage=45, stale-while-revalidate=180','Access-Control-Allow-Origin':'*'},body:out.toString('base64')};
};
